import React from 'react';
import { useEffect, useState } from 'react';

function Settings({authorisedUser, getEmployeeById, updateEmployee, updateAddress}) {

    const [employee, setEmployee] = useState(null);
               
    useEffect(() => {
        console.log("Authorised User:", authorisedUser);
        if (authorisedUser && authorisedUser.employeeID) {
            getEmployeeById(authorisedUser.employeeID)
                .then(data => setEmployee(data)) // Wrap the result in an array to match the existing structure
                .catch(error => console.error("Error fetching employee data:", error));
        }
    }, []);

    const formSubmit = async (event) => {
        event.preventDefault();

        const updatedEmployee = {
            email: employee.email,
            password: employee.password,
            firstName: employee.firstName,
            lastName: employee.lastName,
            position: employee.position,
            role: employee.role,
            active: employee.active,
            employedDate: employee.employedDate
        };
        await updateEmployee(employee.employeeID, updatedEmployee);

        const updatedAddress = {
            postCode: employee.address.postCode,
            street: employee.address.street,
            city: employee.address.city,
            country: employee.address.country
        };

        await updateAddress(employee.address.addressID, updatedAddress);

        //Pop up for success message
        setShowSuccessMessage(true);

        getEmployeeById(employee.employeeID).then((employee) => setEmployee(employee));

        // Prevent URL changes by ensuring no redirection occurs
        window.history.replaceState(null, "", "/settings");
    }

    const handleChange = (event) => {
        const { name, value } = event.target;

        // Check if the field belongs to the address object
        if (["street", "postCode", "city", "country"].includes(name)) {
            setEmployee((prevState) => ({
            ...prevState,
            address: {
                ...prevState.address,
                [name]: value, // Update the specific field in the address object
            },
            }));
        } else {
            // Update fields directly on selectedEmployee
            setEmployee((prevState) => ({
            ...prevState,
            [name]: value,
            }));
        }
    };

    const [showSuccessMessage, setShowSuccessMessage] = useState(false);

    const handleCloseSuccessMessage = () => {
        setShowSuccessMessage(false);
    };





  return (
    <>
    
        <div className='settings-container'>
            <h1>Settings</h1>

            <form className='settings-form' onSubmit={formSubmit}>
                
                <div className='imageProfileContainer'>
                    <div className='imageContainer'>
                        <img src="/images/UserIcon.svg" />
                    </div>

                    <div className='imageBtnContainer'>
                        <button className='addBtn' type="submit">Add Picture</button>
                    </div>
                </div>

                <div className='twoFieldsHolder'>
                    <div className='formField'>
                        <label>Employee ID:</label>
                        { employee &&
                            <input
                                type="text"
                                className='shortInputField'
                                value={employee.employeeID}
                                readOnly />
                        }
                    </div>

                    <div className='formField'>
                        <label>Employeed Date:</label>
                        { employee &&
                            <input
                                type="text"
                                className='shortInputField'
                                value={employee.employedDate} 
                                readOnly/>
                        }
                    </div>
                </div>

                <div className='twoFieldsHolder'>
                    <div className='formField'>
                        <label>Email:</label>
                            { employee &&
                                <input
                                    type="email"
                                    className='longInputField'
                                    value={employee.email}
                                    onChange={handleChange}
                                    name='email' />
                            }
                    </div>

                    <div className='formField'>
                        <label>Password:</label>
                        { employee &&
                            <input
                                type="text"
                                className='shortInputField'
                                value={employee.password}
                                onChange={handleChange}
                                name='password' />
                        }
                    </div>
                </div>

                <div className='twoFieldsHolder'>
                    <div className='formField'>
                        <label>First Name:</label>
                        { employee &&
                            <input
                                type="text"
                                className='longInputField'
                                value={employee.firstName}
                                onChange={handleChange}
                                name='firstName' />
                        }
                    </div>

                    <div className='formField'>
                        <label>Last Name:</label>
                        { employee &&
                            <input
                                type="text"
                                className='longInputField'
                                value={employee.lastName}
                                onChange={handleChange}
                                name='lastName' />
                        }
                    </div>
                </div>

                <div className='formField'>
                    <label>Position:</label>
                    { employee &&
                        <input
                            type="text"
                            className='longInputField'
                            value={employee.position}
                            onChange={handleChange}
                            name='position' />
                    }
                </div>

                <div className='formField'>
                    <label>Postal Code:</label>
                    { employee &&
                        <input
                            type="text"
                            className='shortInputField'
                            value={employee.address.postCode}
                            onChange={handleChange}
                            name='postCode' />
                    }
                </div>

                <div className='twoFieldsHolder'>
                    <div className='formField'>
                        <label>Street:</label>
                        { employee &&
                            <input
                                type="text"
                                className='longInputField'
                                value={employee.address.street}
                                onChange={handleChange}
                                name='street' />
                        }
                    </div>

                    <div className='formField'>
                        <label>City:</label>
                        { employee &&
                            <input
                                type="text"
                                className='longInputField'
                                value={employee.address.city}
                                onChange={handleChange}
                                name='city' />
                        }
                    </div>
                </div>

                <div className='formField'>
                    <label>Country:</label>
                    { employee &&
                        <input
                            type="text"
                            className='longInputField'
                            value={employee.address.country}
                            onChange={handleChange}
                            name='country' />
                    }
                </div>

                <button className='addBtn' type='submit'>Save</button>

            </form>
        </div>

        {showSuccessMessage && (
            <div className='modal'>
                <div className='modal-content'>
                    <span className='close' onClick={handleCloseSuccessMessage}>
                        &times;
                    </span>
                    <h2>Information changed!</h2>
                    <p>Information abouit employee is successfully changed!</p>
                    <button type='submit' onClick={handleCloseSuccessMessage}>
                        OK
                    </button>
                </div>
            </div>
        )}
    </>
  )
}

export default Settings;
